function validate([n, crystals, flowFrom, flowTo]) {
  if (n < 2 || n > 100000) return 'n is between 2 and 10^5.';
  if (crystals.length < 1 || crystals.length > n) return 'crystals lists 1 to n points.';
  if (crystals.some(point => point < 0 || point >= n)) return 'Every crystal sits on a point from 0 to n - 1.';
  if (flowFrom.length !== flowTo.length) return 'flowFrom and flowTo need the same length.';
  if (flowFrom.length < 1 || flowFrom.length > Math.min(200000, n * (n - 1) / 2)) return 'There are 1 to min(2 * 10^5, n * (n - 1) / 2) runes.';
  const seen = new Set();
  for (let i = 0; i < flowFrom.length; i++) {
    const from = flowFrom[i];
    const to = flowTo[i];
    if (from < 0 || from >= n || to < 0 || to >= n) return 'Rune ends are points from 0 to n - 1.';
    if (from === to) return 'A rune links two different points.';
    if (seen.has(from * n + to)) return 'The same rune appears twice.';
    seen.add(from * n + to);
  }
  return null;
}

