function minRunesToAdd(n, crystals, flowFrom, flowTo) {
  const graph = Array.from({ length: n }, () => []);
  const reverse = Array.from({ length: n }, () => []);
  for (let i = 0; i < flowFrom.length; i++) {
    graph[flowFrom[i]].push(flowTo[i]);
    reverse[flowTo[i]].push(flowFrom[i]);
  }

  const order = [];
  const visited = new Array(n).fill(false);
  const nextEdge = new Array(n).fill(0);
  for (let start = 0; start < n; start++) {
    if (visited[start]) continue;
    visited[start] = true;
    const stack = [start];
    while (stack.length > 0) {
      const node = stack[stack.length - 1];
      if (nextEdge[node] < graph[node].length) {
        const next = graph[node][nextEdge[node]];
        nextEdge[node]++;
        if (!visited[next]) {
          visited[next] = true;
          stack.push(next);
        }
      } else {
        order.push(stack.pop());
      }
    }
  }

  const component = new Array(n).fill(-1);
  let components = 0;
  for (let i = n - 1; i >= 0; i--) {
    const root = order[i];
    if (component[root] !== -1) continue;
    component[root] = components;
    const stack = [root];
    while (stack.length > 0) {
      const node = stack.pop();
      for (const prev of reverse[node]) {
        if (component[prev] === -1) {
          component[prev] = components;
          stack.push(prev);
        }
      }
    }
    components++;
  }

  const needsRune = new Array(components).fill(true);
  for (let i = 0; i < flowFrom.length; i++) {
    const target = component[flowTo[i]];
    if (component[flowFrom[i]] !== target) {
      needsRune[target] = false;
    }
  }
  for (const crystal of crystals) {
    needsRune[component[crystal]] = false;
  }
  return needsRune.filter(Boolean).length;
}

