function minRunesToAdd(n, crystals, flowFrom, flowTo) {
  // An added rune can always start at a crystal point, so it is enough to choose the fewest extra
  // starting points that, together with the crystals, reach every point. Try every set of extras.
  const reachesAll = (starts) => {
    const seen = new Set(starts);
    const queue = [...seen];
    while (queue.length > 0) {
      const node = queue.shift();
      for (let i = 0; i < flowFrom.length; i++) {
        if (flowFrom[i] === node && !seen.has(flowTo[i])) {
          seen.add(flowTo[i]);
          queue.push(flowTo[i]);
        }
      }
    }
    return seen.size === n;
  };
  let best = n;
  for (let mask = 0; mask < (1 << n); mask++) {
    const extra = [];
    for (let point = 0; point < n; point++) if (mask & (1 << point)) extra.push(point);
    if (extra.length < best && reachesAll([...crystals, ...extra])) best = extra.length;
  }
  return best;
}

