function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? int(1500, 2000) : int(2, 8);
  const limit = large ? 2000 : Math.min(n * (n - 1) / 2, 12);
  // Shuffle the points; consecutive runs of them become clusters joined into cycles (strongly connected parts).
  const points = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [points[i], points[j]] = [points[j], points[i]];
  }
  const rank = new Array(n);
  points.forEach((point, i) => { rank[point] = i; });
  const seen = new Set();
  const flowFrom = [];
  const flowTo = [];
  const add = (from, to) => {
    if (from === to || flowFrom.length >= limit || seen.has(from * n + to)) return;
    seen.add(from * n + to);
    flowFrom.push(from);
    flowTo.push(to);
  };
  for (let i = 0; i < n;) {
    const length = Math.min(n - i, large ? int(1, 8) : int(1, 4));
    if (length > 1 && rand() < 0.7) for (let k = 0; k < length; k++) add(points[i + k], points[i + (k + 1) % length]);
    i += length;
  }
  // Extra runes mostly point forward in the shuffled order (a DAG between clusters); a few point anywhere.
  const extra = large ? int(200, 1200) : int(0, limit);
  for (let tries = 0; tries < 4 * extra; tries++) {
    let from = Math.floor(rand() * n);
    let to = Math.floor(rand() * n);
    if (rand() < 0.8 && rank[from] > rank[to]) [from, to] = [to, from];
    add(from, to);
    if (flowFrom.length >= limit) break;
  }
  if (flowFrom.length === 0) add(points[0], points[1]);
  const crystalCount = large ? int(1, 40) : rand() < 0.1 ? n : int(1, Math.min(n, 3));
  const pool = Array.from({ length: n }, (_, i) => i);
  const crystals = [];
  for (let k = 0; k < crystalCount; k++) crystals.push(pool.splice(Math.floor(rand() * pool.length), 1)[0]);
  return [n, crystals, flowFrom, flowTo];
}
